using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Windows.Forms;using System.Drawing;using System.Reflection;
namespace LoopPedal {static class VstChecks {
 static void Check(bool v,string label){if(!v)throw new Exception(label);}
 static VstSlot Fixture(int latency,float gain){var history=new float[Math.Max(1,latency)*2];int at=0;return new VstSlot{Name="Delay fixture",TestLatency=latency,TestProcess=audio=>{for(int i=0;i<VstRack.Block;i++){float l=audio[i*2],r=audio[i*2+1];if(latency>0){float oldL=history[at*2],oldR=history[at*2+1];history[at*2]=l;history[at*2+1]=r;l=oldL;r=oldR;at=(at+1)%latency;}audio[i*2]=l*gain;audio[i*2+1]=r*gain;}return true;}};}
 static void Latency(List<string> log){foreach(int route in new[]{0,1,2}){var fx=new MasterFx{Reverb=1,Delay=1,Grain=1,Routing=route,Plugins=new VstRack()};fx.SnapRouting();fx.Plugins.Slots[0]=Fixture(17,1);fx.Plugins.Slots[1]=Fixture(43,1);fx.Plugins.Slots[2]=Fixture(11,1);fx.PreparePlugins();int delay=64+(route==1?71:route==2?54:43);double error=0;for(int i=0;i<48000;i++){float x=(float)(.12*Math.Sin(i*.071)),wl,wr;fx.Process(x,-x,out wl,out wr);if(i>2000)error=Math.Max(error,Math.Abs(x+wl-.12*Math.Sin((i-delay)*.071)));}Check(error<1e-6,"Latency/dry alignment route "+route+" error="+error);log.Add("PASS exact dry/plugin latency alignment route="+route+" delay="+delay+" error="+error);}
 var mix=new MasterFx{Reverb=.5f,Plugins=new VstRack()};mix.Plugins.Slots[0]=Fixture(17,.5f);mix.PreparePlugins();double difference=0;for(int i=0;i<48000;i++){float x=(float)(.12*Math.Sin(i*.041)),l,r;mix.Process(x,x,out l,out r);if(i>12000)difference=Math.Max(difference,Math.Abs(x+l-.09*Math.Sin((i-81)*.041)));}Check(difference<1e-6,"Latency matched wet/dry mix");log.Add("PASS fractional plugin mix retains aligned dry signal");}
 public static void Run(){var log=new List<string>();try{Latency(log);string root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonProgramFiles),"VST3");foreach(string name in new[]{"TAL-Reverb-2","TAL-Chorus-LX","ValhallaSupermassive"}){string path=Path.Combine(root,name+".vst3");if(!File.Exists(path)&&!Directory.Exists(path))continue;using(var instance=new VstInstance(path,null)){var samples=new float[VstRack.Block*2];double energy=0,peak=0;for(int block=0;block<1500;block++){for(int i=0;i<VstRack.Block;i++)samples[i*2]=samples[i*2+1]=block<500?(float)(.1*Math.Sin((block*VstRack.Block+i)*.06)):0;Check(instance.Process(samples,120),"Native process "+name);foreach(float v in samples){Check(!float.IsNaN(v)&&!float.IsInfinity(v),"Finite plugin audio");energy+=v*v;peak=Math.Max(peak,Math.Abs(v));}}Check(energy>.01&&peak<4,"Real plugin energy/level "+name);var state=instance.Snapshot();Check(state.Length>0,"Native plugin state");using(var restored=new VstInstance(path,state))Check(restored.Name==instance.Name,"Native state restoration");log.Add("PASS real VST3 "+name+" audio energy="+energy+" peak="+peak+" state="+state.Length);}}
 var soak=new MasterFx{Reverb=1,Delay=1,Grain=1,Plugins=new VstRack()};string[] installed={"TAL-Reverb-2","TAL-Chorus-LX","ValhallaSupermassive"};bool available=true;for(int i=0;i<3;i++){string path=Path.Combine(root,installed[i]+".vst3");if(!File.Exists(path)&&!Directory.Exists(path)){available=false;break;}soak.Plugins.Slots[i]=new VstSlot{Path=path,Name=installed[i]};}if(available){soak.PreparePlugins();var watch=System.Diagnostics.Stopwatch.StartNew();double peak=0;for(int i=0;i<48000*60;i++){float l,r;soak.Process(0,0,out l,out r);peak=Math.Max(peak,Math.Max(Math.Abs(l),Math.Abs(r)));}watch.Stop();Check(peak<.00001,"Silent plugin rack idle noise");log.Add("PASS 60 seconds simulated silent three-plugin rack, peak="+peak+", wall="+watch.ElapsedMilliseconds+" ms");foreach(var slot in soak.Plugins.Slots)if(slot.Instance!=null)slot.Instance.Dispose();}
 using(var form=new Pedal(true)){form.Location=new Point(-20000,-20000);form.Show();form.VerifyVstUi(log);form.Close();}File.WriteAllLines(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"vst-tests.txt"),log);}catch(Exception ex){log.Add("FAIL "+ex);File.WriteAllLines(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"vst-tests.txt"),log);Environment.ExitCode=1;}finally{VstInstance.Shutdown();}}
}
partial class Pedal {
 public void VerifyVstUi(List<string> log){PreviewLayers();Application.DoEvents();fxMenuPad.PerformClick();Application.DoEvents();var tabs=fxSurface.Controls.Find("MasterFxTabs",true).Single();var tab=tabs.Controls.OfType<FxTabButton>().Single(b=>b.Effect==0);typeof(Control).GetMethod("OnMouseUp",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(tab,new object[]{new MouseEventArgs(MouseButtons.Right,1,12,12,0)});Application.DoEvents();if(lastVstMenu==null||!lastVstMenu.Items.Cast<ToolStripItem>().Any(item=>item.Text=="Replace with VST3…"))throw new Exception("VST3 right-click action");lastVstMenu.Close();string path=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonProgramFiles),"VST3/TAL-Reverb-2.vst3");if(!File.Exists(path)&&!Directory.Exists(path)){log.Add("SKIP editor/project test: TAL-Reverb-2 not installed");return;}ReplaceVst(0,path,()=>{});var slot=loopers[0].Fx.Plugins.Slots[0];if(slot.Instance==null)throw new Exception("Replacement runtime missing");slot.Instance.ShowEditor(this,null);Application.DoEvents();if(slot.Instance.Editor==null||slot.Instance.Editor.ClientSize.Width<100)throw new Exception("Native editor attach");slot.Instance.Editor.Close();tabs.Controls.OfType<FxTabButton>().Single(b=>b.Effect==1).PerformClick();Application.DoEvents();tab.PerformClick();Application.DoEvents();if(slot.Instance.EmbeddedHost==null||slot.Instance.Editor!=null)throw new Exception("Editor not embedded");var sendLevel=fxSurface.Controls.Find("MasterFxLevels",true).Single().Controls.OfType<Knob>().Single(k=>k.Tag.ToString()=="FX.0");if(sendLevel.Caption!=slot.Name)throw new Exception("Plugin send label");foreach(int width in new[]{1100,1500}){Width=width;Height=880;Application.DoEvents();var host=slot.Instance.EmbeddedHost;if(host==null||host.Parent==null)throw new Exception("Embedded view lost during resize");log.Add("PASS embedded editor size="+host.Size+" viewport="+host.Parent.ClientSize);}using(var image=new Bitmap(fxSurface.Width,fxSurface.Height)){fxSurface.DrawToBitmap(image,new Rectangle(Point.Empty,fxSurface.Size));image.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"vst-controls-ui.png"));}slot.Instance.ShowEditor(this,null);Application.DoEvents();if(slot.Instance.Editor==null||slot.Instance.EmbeddedHost!=null)throw new Exception("Pop out failed");slot.Instance.Editor.Close();tabs.Controls.OfType<FxTabButton>().Single(b=>b.Effect==1).PerformClick();Application.DoEvents();tab.PerformClick();Application.DoEvents();if(slot.Instance.EmbeddedHost==null)throw new Exception("Reattach after popout");slot.Bypass=true;loopers[0].Fx.Reverb=.6f;var project=PerformanceProject.Capture(loopers);ulong stamp=project.Stamp();for(int i=0;i<256;i++){float l,r;loopers[0].Fx.Process(.1f,.1f,out l,out r);}if(PerformanceProject.Capture(loopers).Stamp()!=stamp)throw new Exception("Playback dirtied plugin state");string file=Path.Combine(Path.GetTempPath(),"Agent-VST-"+Guid.NewGuid()+".agw");try{project.Save(file);var loaded=PerformanceProject.Load(file);var loadedSlot=loaded.State.Banks[0].Fx.Plugins.Slots[0];if(loadedSlot.Path!=path||!loadedSlot.Bypass||loadedSlot.State.Length==0)throw new Exception("Project plugin state");loaded.State.Banks[0].Fx.PreparePlugins();if(loadedSlot.Instance==null)throw new Exception("Loaded plugin preparation");loadedSlot.Instance.Dispose();loadedSlot.Instance=null;loadedSlot.Path+=".missing";loaded.State.Banks[0].Fx.PreparePlugins();if(loadedSlot.Instance!=null||loadedSlot.Error==null)throw new Exception("Missing plugin handling");for(int i=0;i<512;i++){float l,r;loaded.State.Banks[0].Fx.Process(.1f,.1f,out l,out r);if(i>128&&Math.Abs(.1f+l-.1f)>1e-6)throw new Exception("Missing plugin dry passthrough");}}finally{if(File.Exists(file))File.Delete(file);}log.Add("PASS actual right-click plugin menu, embedded editor/resizing/tab detach/popout/reattach, bypass, project state/reload, stable dirty tracking and missing-plugin dry fallback");}
}}
